//! Numerical parity with the upstream Python implementations.
//!
//! These tests download models and compare against fixtures generated by
//! `scripts/reference/*.py`. Run them with
//! `PARITY_FIXTURES=<dir> cargo test --release --test parity -- --ignored`.

use std::path::PathBuf;

use semantic_voice_local::tts::Tts;

fn fixture(name: &str) -> Vec<f32> {
    let dir = PathBuf::from(std::env::var("PARITY_FIXTURES").expect("PARITY_FIXTURES is not set"));
    let bytes = std::fs::read(dir.join(name)).unwrap_or_else(|e| panic!("{name}: {e}"));
    let (chunks, _) = bytes.as_chunks::<4>();
    chunks.iter().map(|b| f32::from_le_bytes(*b)).collect()
}

/// At temperature 0 generation is deterministic, so the audio must match the reference.
fn check_tts(model: &str) {
    let tts = Tts::load(model).unwrap();
    let voice = tts.voice("alba").unwrap();
    let mut options = tts.default_options();
    options.temperature = 0.0;
    let audio = tts
        .synthesize_with(
            "Hello world. This is a test of the Rust port.",
            &voice,
            &options,
        )
        .unwrap();
    let reference = fixture(&format!("tts_{model}.f32"));
    let max_diff = audio
        .samples()
        .iter()
        .zip(&reference)
        .map(|(a, b)| (a - b).abs())
        .fold(0.0f32, f32::max);
    println!(
        "{model}: {} vs {} samples, max diff {max_diff}",
        audio.len(),
        reference.len()
    );
    assert_eq!(audio.len(), reference.len());
    assert!(max_diff < 1e-2, "max diff {max_diff}");
}

#[test]
#[ignore = "downloads models, needs PARITY_FIXTURES"]
fn tts_english() {
    check_tts("english");
}

#[test]
#[ignore = "downloads models, needs PARITY_FIXTURES"]
fn tts_english_2m() {
    check_tts("english_2m_2026-10");
}

/// Greedy decoding is deterministic: the transcript must match the reference.
#[test]
#[ignore = "downloads models, needs PARITY_FIXTURES"]
fn stt_1b() {
    use semantic_voice_local::{
        Audio,
        stt::{Stt, SttModel},
    };

    let stt = Stt::load(SttModel::EnFr1b).unwrap();
    let audio = Audio::new(fixture("stt_bria.f32"), 24_000);
    let started = std::time::Instant::now();
    let transcript = stt.transcribe(&audio).unwrap();
    println!(
        "transcribed {:.1?} in {:.1?}",
        audio.duration(),
        started.elapsed()
    );
    let dir = PathBuf::from(std::env::var("PARITY_FIXTURES").unwrap());
    let reference: serde_json::Value =
        serde_json::from_slice(&std::fs::read(dir.join("stt_bria.json")).unwrap()).unwrap();
    let normalize = |s: &str| s.split_whitespace().collect::<Vec<_>>().join(" ");
    println!("{}", transcript.text);
    for word in transcript.words.iter().take(5) {
        println!("{word:?}");
    }
    assert_eq!(
        normalize(&transcript.text),
        normalize(reference["text"].as_str().unwrap())
    );
}

/// Token ids, decoding and text chunking on tricky inputs, for each tokenizer format.
#[test]
#[ignore = "downloads models, needs PARITY_FIXTURES"]
fn text_processing() {
    let dir = PathBuf::from(std::env::var("PARITY_FIXTURES").unwrap());
    let reference: serde_json::Value =
        serde_json::from_slice(&std::fs::read(dir.join("text.json")).unwrap()).unwrap();
    for (model, fixture) in reference.as_object().unwrap() {
        let tokenizer =
            semantic_voice_local::Tokenizer::load(fixture["tokenizer"].as_str().unwrap()).unwrap();
        let tts = Tts::load(model).unwrap();
        for case in fixture["cases"].as_array().unwrap() {
            let text = case["text"].as_str().unwrap();
            let ids: Vec<u32> = serde_json::from_value(case["ids"].clone()).unwrap();
            let chunks: Vec<String> = serde_json::from_value(case["chunks"].clone()).unwrap();
            assert_eq!(
                tokenizer.encode(text).unwrap(),
                ids,
                "{model}: ids of {text:?}"
            );
            assert_eq!(
                tokenizer.decode(&ids),
                case["decoded"].as_str().unwrap(),
                "{model}: decode of {text:?}"
            );
            assert_eq!(
                tts.split_text(text, 50).unwrap(),
                chunks,
                "{model}: chunks of {text:?}"
            );
        }
    }
}
